import com.google.common.io.Files;
import com.google.javascript.rhino.jstype.StaticSourceFile;
import java.io.*;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.Serializable;
import java.io.StringReader;
import java.math.*;
import java.nio.charset.Charset;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

public class SourceFile_getLine_TriageGen0Test {

    @Test
    public void testGetLine_BasicFunctionality() throws IOException {
        String code = "line1\nline2\nline3\nline4";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        assertEquals("line1", sourceFile.getLine(1));
        assertEquals("line2", sourceFile.getLine(2));
        assertEquals("line3", sourceFile.getLine(3));
        assertEquals("line4", sourceFile.getLine(4));
    }

    @Test
    public void testGetLine_CachingOptimization() throws IOException {
        String code = "line1\nline2\nline3\nline4";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        // First call: start from beginning
        assertEquals("line1", sourceFile.getLine(1));

        // Second call: lineNumber (3) >= lastLine (1), should use lastOffset
        assertEquals("line3", sourceFile.getLine(3));

        // Third call: lineNumber (2) < lastLine (3), should start from beginning (pos=0, startLine=1)
        assertEquals("line2", sourceFile.getLine(2));
    }

    @Test
    public void testGetLine_IOException() throws IOException {
        // Using spy to force an IOException in getCode()
        SourceFile sourceFile = spy(SourceFile.fromCode("test.js", "code"));
        doThrow(new IOException("Mock error")).when(sourceFile).getCode();

        assertNull(sourceFile.getLine(1));
    }

    @Test
    public void testGetLine_LineNotFound_TooHigh() throws IOException {
        String code = "line1\nline2";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        // Requesting a line that doesn't exist because nextpos returns -1 in the loop
        assertNull(sourceFile.getLine(5));
    }

    @Test
    public void testGetLine_LastLineEdgeCase() throws IOException {
        // The implementation has a specific check: 
        // if (js.indexOf('\n', pos) == -1) { return null; }
        // This means if the last line of the file does NOT end with a newline, 
        // the current implementation returns null.

        String code = "line1\nline2";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        // Line 1 is fine because there is a '\n' after it
        assertEquals("line1", sourceFile.getLine(1));

        // Line 2 is the last line and has no trailing '\n'. 
        // Based on the provided code logic: js.indexOf('\n', pos) will be -1.
        assertNull(sourceFile.getLine(2));
    }

    @Test
    public void testGetLine_LastLineWithNewline() throws IOException {
        // If the file ends with a newline, the last line can be retrieved
        String code = "line1\nline2\n";
        SourceFile sourceFile = SourceFile.fromCode("test.js", code);

        assertEquals("line1", sourceFile.getLine(1));
        assertEquals("line2", sourceFile.getLine(2));
    }

    @Test
    public void testGetLine_EmptyFile() throws IOException {
        SourceFile sourceFile = SourceFile.fromCode("test.js", "");
        assertNull(sourceFile.getLine(1));
    }

    @Test
    public void testGetLine_SingleLineNoNewline() throws IOException {
        SourceFile sourceFile = SourceFile.fromCode("test.js", "onlyline");
        assertNull(sourceFile.getLine(1));
    }
}
